-- Chantier 2 : prix estimés (worker/prix.js). Ajouts seulement.
-- AUCUNE valeur ci-dessous n'est officielle : ce sont des exemples (« À REMPLACER ») ou des reprises de la presse
-- (« À VÉRIFIER »), à faire valider par le transitaire. Source principale de la LF 2026 : texte officiel (loi n° 2025-17
-- du 12/12/2025, JORT n° 148, traduction française) https://lake.jort.tn/journal-officiel/fr/2025/148.pdf ; il prime sur la presse.
-- À consulter aussi : note commune n° 6 de la DGELF. Aucun prix n'est affiché au public (prix_publics_actifs).

-- Paramètres du calcul. Valeurs en texte (nombres à point décimal, booléens 'true'/'false', '' = vide).
CREATE TABLE parametres_prix (
  cle TEXT PRIMARY KEY,
  valeur TEXT NOT NULL,
  unite TEXT,
  note TEXT,
  mis_a_jour TEXT NOT NULL,
  mis_a_jour_par INTEGER REFERENCES users(id) ON DELETE SET NULL
);
