-- Régimes douaniers. statut_verification reste 'a_verifier' tant que le transitaire n'a pas validé les valeurs.
CREATE TABLE regimes_douaniers (
  code TEXT PRIMARY KEY,
  libelle TEXT NOT NULL,
  public TEXT NOT NULL CHECK (public IN ('resident', 'tre')),
  actif INTEGER NOT NULL DEFAULT 1 CHECK (actif IN (0, 1)),
  statut_verification TEXT NOT NULL DEFAULT 'a_verifier' CHECK (statut_verification IN ('a_verifier', 'verifie')),
  source TEXT,
  note TEXT
);
INSERT INTO regimes_douaniers (code, libelle, public, actif, statut_verification, source, note) VALUES
  ('resident_droit_commun', 'Résident, droit commun', 'resident', 1, 'a_verifier', NULL,
   'Importation par un résident, droits normaux. Toutes les valeurs sont des exemples À REMPLACER par le transitaire.'),
  ('resident_phev_lf2026', 'Résident, hybride rechargeable (LF 2026)', 'resident', 1, 'a_verifier',
   'https://lake.jort.tn/journal-officiel/fr/2025/148.pdf (source principale) ; https://finco.tn/blog/voitures-hybrides-electriques-tunisie-2026 ; https://managers.tn/2026/03/17/voitures-hybrides-et-electriques-ce-que-vous-paierez-moins-cette-2026-en-tunisie/',
   'Art. 47 LF 2026 (loi n° 2025-17, JORT n° 148), en vigueur depuis le 01/01/2026 : droit de consommation exonéré et TVA 7 % (confirmés par le texte). Droit de douane 0 % seulement pour Ex 87.02 et Ex 87.04 selon l''art. 47 LF 2026 (JORT 148) ; voitures particulières 87.03 : droit commun, à confirmer avec le transitaire. Carte grise et vignette -50 % selon la presse, non vérifié dans le texte (renvoi à l''art. 77 de la loi 82-91 et à l''art. 22 de la loi 84-2) : À VÉRIFIER. La loi ne distingue ni neuf et occasion, ni FCR et droit commun. Condition : moteur thermique et moteur électrique rechargeable par branchement externe. À consulter aussi : note commune n° 6 de la DGELF.'),
  ('resident_hev_lf2026', 'Résident, hybride non rechargeable (LF 2026)', 'resident', 1, 'a_verifier',
   'https://lake.jort.tn/journal-officiel/fr/2025/148.pdf (source principale) ; https://finco.tn/blog/voitures-hybrides-electriques-tunisie-2026 ; https://managers.tn/2026/03/17/voitures-hybrides-et-electriques-ce-que-vous-paierez-moins-cette-2026-en-tunisie/',
   'Art. 47 LF 2026 (JORT n° 148), en vigueur depuis le 01/01/2026 : droit de consommation -50 % pour l''essence ≤ 1 700 cm³ et le diesel « mixte » ≤ 2 100 cm³ (confirmé par le texte) ; taxe de maîtrise de l''énergie -50 % pour l''essence ≤ 1 700 cm³ (pas de colonne dans la grille, non comptée) ; TVA et droits de douane : droit commun. La loi ne distingue ni neuf et occasion, ni FCR et droit commun. Valeurs de base du droit commun : exemples À VÉRIFIER.'),
  ('resident_electrique_lf2026', 'Résident, électrique (LF 2026)', 'resident', 1, 'a_verifier',
   'https://lake.jort.tn/journal-officiel/fr/2025/148.pdf (source principale) ; https://finco.tn/blog/voitures-hybrides-electriques-tunisie-2026',
   'Art. 47 LF 2026 (JORT n° 148), en vigueur depuis le 01/01/2026 : droit de consommation exonéré, TVA 7 %. Droit de douane des voitures particulières non précisé par l''art. 47 : droit commun, À VÉRIFIER. Carte grise et vignette -50 % selon la presse : À VÉRIFIER. La loi ne distingue ni neuf et occasion, ni FCR et droit commun.'),
  ('fcr_classique', 'TRE, franchise FCR', 'tre', 1, 'a_verifier',
   'https://old.douane.gov.tn/index.php?id=126 (cité par un moteur de recherche, page non lue directement)',
   'Tunisiens résidant à l''étranger. Véhicule de 5 ans au plus, compté depuis la première mise en circulation ; FCR utilisable une fois tous les 10 ans (décret n° 2024-370). Part payée des droits et taxes : 25 % (tourisme essence ≤ 2 000 cm³, diesel ≤ 2 500 cm³), 30 % au-delà ; électriques et utilitaires à 25 % selon des extraits de la Douane. Divergence : un ancien guide applique 30 % à tous les diesels. Droits calculés sur la valeur en douane selon type et cylindrée. À VÉRIFIER.');

-- Grille des droits. Une ligne = un régime, un carburant ('*' = tous les autres) et une tranche de cylindrée
-- (cylindree_max NULL = sans limite). Barème du droit de consommation : commentaire LF 2026 InFirst (non officiel).
-- Droit de douane des voitures particulières (87.03) non trouvé : 20 % d'exemple À REMPLACER, sauf électriques (0 %). Les lignes LF 2026 et FCR sont complètes : leurs pourcentages sont ceux du droit
-- commun déjà réduits (LF 2026) ou recopiés (FCR, avec part_payee_pct). Modifier une ligne de droit commun ne met pas
-- à jour les autres : les notes le rappellent.
CREATE TABLE grille_droits (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  regime TEXT NOT NULL REFERENCES regimes_douaniers(code),
  carburant TEXT NOT NULL CHECK (carburant IN ('essence', 'diesel', 'hybride', 'hybride_rechargeable', 'electrique', '*')),
  cylindree_min INTEGER NOT NULL DEFAULT 0,
  cylindree_max INTEGER,
  droits_douane_pct REAL NOT NULL,
  droit_consommation_pct REAL NOT NULL,
  tva_pct REAL NOT NULL,
  reduction_immatriculation_pct REAL NOT NULL DEFAULT 0,
  part_payee_pct REAL NOT NULL DEFAULT 100,
  note TEXT NOT NULL
);
CREATE INDEX grille_droits_regime ON grille_droits(regime, carburant);
